#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: deploy do Mural ONDA (Supabase de produção + Vercel).
# Rodar da raiz do repositório: bash scripts/wizard-deploy.sh
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=10
ENV_FILE=".env.producao"   # ignorado pelo git (.env*); não mexe no .env.local do Supabase local
REPO="lucasSCsantos/onda"
BRANCH_APP="feat/01-esqueleto-app-instalavel"

banner "Mural ONDA: deploy de produção"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Código na main e no GitHub"
say "A Vercel publica a branch main. Vamos trazer o app da branch $BRANCH_APP para a main e enviar ao GitHub."
note "Branch atual: $(git branch --show-current)"
if [[ -n "$(git status --porcelain --untracked-files=no)" ]]; then
  warn "Há alterações não commitadas. Commite ou guarde (git stash) antes de seguir."
  pause "Resolva e pressione Enter"
fi
if confirm "Mesclar $BRANCH_APP na main (fast-forward) e enviar main e $BRANCH_APP para origin?"; then
  git switch main
  git merge --ff-only "$BRANCH_APP"
  git push -u origin main
  git push -u origin "$BRANCH_APP"
  say "✓ main e $BRANCH_APP enviadas."
else
  SKIPPED+=("mesclar $BRANCH_APP na main e git push")
  warn "Pulado. A Vercel só publica depois que a main tiver o app."
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Supabase: criar o projeto de produção"
open_url "https://supabase.com/dashboard/new/_"
step "Escolha a organização e clique em New project."
step "Nome: mural-onda. Região: South America (São Paulo)."
step "Gere uma senha forte para o banco e guarde-a no seu gerenciador de senhas."
step "Clique em Create new project e espere terminar (1 a 2 minutos)."
step "O endereço da página fica …/dashboard/project/<ref>. Copie esse <ref> (20 letras)."
ask SUPABASE_PROJECT_REF "Cole o project ref:"
write_env SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"
NEXT_PUBLIC_SUPABASE_URL="https://${SUPABASE_PROJECT_REF}.supabase.co"
write_env NEXT_PUBLIC_SUPABASE_URL "$NEXT_PUBLIC_SUPABASE_URL"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Supabase: aplicar as migrações"
say "O CLI do Supabase vai abrir o navegador para você entrar, ligar este repositório ao projeto e criar as tabelas."
step "Quando pedir a senha do banco, use a que você criou na etapa anterior."
pnpm exec supabase login
pnpm exec supabase link --project-ref "$SUPABASE_PROJECT_REF"
say "Migrações que serão aplicadas:"
ls supabase/migrations
if confirm "Aplicar as migrações no banco de produção?"; then
  pnpm exec supabase db push
else
  SKIPPED+=("pnpm exec supabase db push")
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Supabase: chave pública do app"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/settings/api-keys"
step "Na aba de chaves, copie a Publishable key (começa com sb_publishable_)."
note "Se a sua tela só mostrar chaves antigas, a anon public também serve."
warn "Nunca copie a secret / service_role: ela ignora as regras de acesso."
ask NEXT_PUBLIC_SUPABASE_ANON_KEY "Cole a chave pública:"
write_env NEXT_PUBLIC_SUPABASE_ANON_KEY "$NEXT_PUBLIC_SUPABASE_ANON_KEY"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Vercel: importar o repositório"
open_url "https://vercel.com/new"
step "Em Import Git Repository, escolha $REPO (se não aparecer, clique em Adjust GitHub App Permissions e libere o repositório)."
step "Framework Preset: Next.js (detectado sozinho). Deixe os comandos padrão."
step "Abra Environment Variables e adicione as duas:"
say "    NEXT_PUBLIC_SUPABASE_URL      = $NEXT_PUBLIC_SUPABASE_URL"
say "    NEXT_PUBLIC_SUPABASE_ANON_KEY = (a chave que você colou na etapa anterior)"
step "Clique em Deploy e espere o build terminar."
step "Na tela de sucesso, copie o domínio de produção (algo como mural-onda.vercel.app)."
ask APP_URL "Cole a URL de produção (com https://):"
APP_URL="${APP_URL%/}"
write_env APP_URL "$APP_URL"
note "Daqui em diante, cada push na main publica sozinho, e cada PR ganha uma prévia."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Supabase: endereços de login"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/auth/url-configuration"
step "Site URL: $APP_URL"
step "Redirect URLs → Add URL: ${APP_URL}/**"
step "Clique em Save."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Supabase: senha mínima e e-mail em português"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/auth/providers"
step "Em Email, ajuste Minimum password length para 8 (o app usa esse valor) e salve."
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/auth/templates"
step "Abra o modelo Reset Password."
step "Subject: Mural ONDA: crie uma nova senha"
step "Body: cole o conteúdo abaixo (o mesmo de supabase/templates/recuperar-senha.html) e salve."
printf '\n'
sed 's/^/      /' supabase/templates/recuperar-senha.html
printf '\n'
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "E-mail: SMTP próprio com Resend"
say "O e-mail embutido do Supabase só entrega para membros da organização. Para os líderes receberem links, use um SMTP próprio."
warn "O Resend só envia para outras pessoas a partir de um domínio verificado (ex.: onda.suaigreja.com.br)."
note "Sem domínio? Alternativa: SMTP do Gmail com senha de app (host smtp.gmail.com, porta 465)."
if confirm "Configurar o Resend agora?"; then
  open_url "https://resend.com/domains"
  step "Adicione e verifique o seu domínio (crie os registros DNS que o Resend mostrar)."
  open_url "https://resend.com/api-keys"
  step "Crie uma API key com permissão Sending access e copie (começa com re_)."
  ask_secret RESEND_API_KEY "Cole a API key (não fica gravada):"
  ask EMAIL_REMETENTE "E-mail remetente, no domínio verificado (ex.: mural@seudominio.com.br):"
  write_env EMAIL_REMETENTE "$EMAIL_REMETENTE"
  open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/auth/smtp"
  step "Ative Enable Custom SMTP e preencha:"
  say "    Sender email: $EMAIL_REMETENTE"
  say "    Sender name:  Mural ONDA"
  say "    Host: smtp.resend.com   Port: 465   Username: resend"
  say "    Password: (a API key que você acabou de colar)"
  step "Clique em Save."
  unset RESEND_API_KEY
else
  SKIPPED+=("SMTP próprio no Supabase (Authentication → SMTP)")
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Sua conta no Mural"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/auth/users"
step "Clique em Add user → Create new user."
step "Digite seu e-mail e uma senha (8+ caracteres), marque Auto Confirm User e crie."
note "O wizard não pede nem guarda sua senha."
ask NOME_LUCAS "Como seu nome deve aparecer no app?"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/sql/new"
step "Cole e rode este SQL, trocando o e-mail pelo seu:"
say "    update public.perfis set nome = '${NOME_LUCAS//\'/\'\'}'"
say "    where id = (select id from auth.users where email = 'SEU-EMAIL-AQUI');"
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Conferir"
open_url "$APP_URL"
step "Entre com sua conta: deve aparecer \"Olá, ${NOME_LUCAS}!\"."
step "Saia e teste Esqueci minha senha: o e-mail deve chegar em português e levar à tela de nova senha."
step "No celular, abra $APP_URL e use Adicionar à tela inicial: o ícone da onda deve aparecer."
pause "Tudo certo? Pressione Enter"

finish
note "Valores de produção guardados em $ENV_FILE (fora do git)."
